Fixpoint ft_dig4 (r : Z) (bs : list Z) {struct bs} : Z * list Z :=
  match bs with
  | b0 :: b1 :: b2 :: b3 :: rest => ft_dig4 ((5 * r + Z.lor (u32le b0 b1 b2 b3) 0x20202020) mod 2^32) rest
  | _ => (r, bs)
  end.
Fixpoint ft_dig1 (r : Z) (bs : list Z) : Z :=
  match bs with
  | [] => r
  | b :: rest => ft_dig1 ((5 * r + Z.lor b 32) mod 2^32) rest
  end.
Definition ft_digest_from (r : Z) (bs : list Z) : Z := let (r', rest) := ft_dig4 r bs in ft_dig1 r' rest.
Definition ft_digest (bs : list Z) : Z := ft_digest_from 0 bs.

