Lemma ft_ptr_range : forall i, (i < 130)%nat -> 0x10424 <= ft_ptr i /\ ft_ptr i + ft_len i <= 0x14ca1.
Proof.
  intros i Hi.
  assert (G : forallb (fun i : nat => (0x10424 <=? ft_ptr i) && (ft_ptr i + ft_len i <=? 0x14ca1)) (seq 0 130) = true) by (vm_compute; reflexivity).
  rewrite forallb_forall in G. specialize (G i ltac:(apply in_seq; lia)). apply andb_prop in G. destruct G as [G1 G2].
  apply Z.leb_le in G1. apply Z.leb_le in G2. lia.
Qed.
